 {tab==="Proficiencies"&&<><Panel title="PROFICIENCIES & TRAINING"><div className="read-only-details">{[["Saving Throws",c.savingThrows.join(", ")||"None"],["Skills",(c.skillProficiencies||[]).join(", ")||"None"],["Expertise",(c.skillExpertise||[]).join(", ")||"None"],["Armor",(c.armorProficiencies||[]).join(", ")||"Not recorded"],["Weapons",(c.weaponProficiencies||[]).join(", ")||"Not recorded"],["Tools",(c.toolProficiencies||[]).join(", ")||"Not recorded"],["Languages",(c.languages||[]).join(", ")||"Not recorded"]].map(([label,value])=><div key={label}><small>{label}</small><b>{value}</b></div>)}</div></Panel></>}
 {tab==="Background"&&<Panel title="BACKGROUND"><div className="read-only-details">{[["Background",c.background],["Species",c.species],["Class",c.className],["Subclass",c.subclass],["Level",c.level]].map(([label,value])=><div key={label}><small>{label}</small><b>{value||"Not recorded"}</b></div>)}</div><p>{c.backgroundDescription||"No background details recorded."}</p></Panel>}
 {tab==="Creatures"&&<Panel title="EXTRAS: CREATURES"><p>{(c.creatures||[]).length?c.creatures.map(x=>typeof x==="string"?x:x.name).join(", "):"No creatures recorded."}</p></Panel>}
