 const addCatalogItem=(entry,target="")=>{const item={...structuredClone(entry),id:crypto.randomUUID?.()||String(Date.now()+Math.random()),quantity:Math.max(1,Number(quantity)||1),equipped:false,attuned:false,containerId:target||"",source:entry.source||"5e Core Rules"};change(normalizeInventory([...normalized,item]));setSelected(null);setQuantity(1);setAddMenu("");setView("inventory");};
